-- Daily challenges for 2026-11-16: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-11-16. The routine loads the same rows in
-- re-runnable pieces from tools/challenges_sync.py; the GitHub workflow applies this file once
-- the SUPABASE_DB_URL secret is set.

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('being-a-good-sport', 'Being a Good Sport', 'For anyone who wants to win kindly, lose gracefully and enjoy the game either way. Each day is one small way to play fair, cheer others on and keep your cool in games, sports and friendly contests.', 'Play', 365, array['Emotion Regulation', 'Relationships']::text[], 1, '2026-11-16T17:00:00+00:00'::timestamptz),
  ('making-a-calmer-workspace', 'Making a Calmer Workspace', 'For anyone whose desk, kitchen table or work corner feels cluttered or tense. Each day is one small change to the place you work, so it feels a little calmer, kinder and easier to settle into.', 'Work', 365, array['Work', 'Stress', 'Habits']::text[], 1, '2026-11-16T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('being-a-good-sport', 'making-a-calmer-workspace');

